class StudentAccount:
    def __init__(self, username, initial_progress=0.0):
        self.username = username
        self._progress = 0.0
        self.progress = initial_progress # Uses setter validation

    @property
    def progress(self):
        """Getter for progress percentage."""
        return self._progress

    @progress.setter
    def progress(self, value):
        if not (0.0 <= value <= 100.0):
            print(f"Validation Warning: Progress must be between 0.0 and 100.0. Given: {value}")
            return
        self._progress = round(value, 1)

