from dataclasses import dataclass
from typing import List, Set

@dataclass
class Lesson:
    id: int
    title: str
    duration: int

class StudentEnrollment:
    def __init__(self, student_name: str, course_title: str, lessons: List[Lesson]):
        self.student_name = student_name
        self.course_title = course_title
        self.lessons = lessons
        self._completed_ids: Set[int] = set()

    def complete_lesson(self, lesson_id: int):
        if any(l.id == lesson_id for l in self.lessons):
            self._completed_ids.add(lesson_id)

    @property
    def progress_percentage(self) -> float:
        if not self.lessons: return 0.0
        return round((len(self._completed_ids) / len(self.lessons)) * 100.0, 1)

