def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("Error: Cannot divide by zero!")
        return None
    except TypeError as e:
        print(f"Error: Invalid argument type - {e}")
        return None
    else:
        return result
    finally:
        pass

print("10 / 2 =", safe_divide(10, 2))
print("10 / 0 =", safe_divide(10, 0))

class DuplicateEnrollmentError(Exception):
    def __init__(self, student, course):
        super().__init__(f"Student '{student}' is already enrolled in '{course}'!")
        self.student = student
        self.course = course

def enroll(student, course, enrolled_students):
    if student in enrolled_students:
        raise DuplicateEnrollmentError(student, course)
    enrolled_students.add(student)
    print(f"Enrolled {student} in {course}")

active_roster = {"Alex Morgan"}
try:
    enroll("Alex Morgan", "Python Masterclass", active_roster)
except DuplicateEnrollmentError as e:
    print(f"Domain Error: {e}")

