import functools
import time

def timer_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = (time.perf_counter() - start) * 1000
        print(f"[PERF] '{func.__name__}' executed in {elapsed:.3f} ms")
        return result
    return wrapper

@timer_decorator
def compute_data(n):
    return sum(i * i for i in range(n))

res = compute_data(50000)
print(f"Result: {res}")

def simulate_api_fetch(status_code, raw_body):
    if status_code == 404:
        raise ValueError("Resource not found (HTTP 404)")
    if status_code >= 500:
        raise RuntimeError("Upstream server error (HTTP 500)")
    try:
        import json
        return json.loads(raw_body)
    except Exception as e:
        raise ValueError(f"Malformed JSON response: {e}")

try:
    simulate_api_fetch(404, "")
except ValueError as err:
    print(f"Captured API client error: {err}")

