class UnitConverter:
    @staticmethod
    def celsius_to_fahrenheit(c: float) -> float:
        return (c * 9/5) + 32

    @staticmethod
    def km_to_miles(km: float) -> float:
        return km * 0.621371

    @staticmethod
    def bytes_to_mb(b: int) -> float:
        return b / (1024 * 1024)

