class ContactBook:
    def __init__(self):
        self.contacts = {}

    def add(self, name, phone, email):
        self.contacts[name.lower()] = {"name": name, "phone": phone, "email": email}

    def search(self, term):
        term = term.lower()
        return [c for c in self.contacts.values() if term in c["name"].lower() or term in c["email"].lower()]

