class QuizApp:
    def __init__(self, questions):
        self.questions = questions
        self.score = 0

    def evaluate(self, user_answers):
        self.score = 0
        for q, ans in zip(self.questions, user_answers):
            if ans == q["answer"]:
                self.score += 1
        return round((self.score / len(self.questions)) * 100.0, 1)

